{"content": "// Task CRUD and status transitions.
// Partially implemented: basic storage and CRUD methods exist.
// Missing/buggy: no input validation, no user existence check,
// no status machine, no permission checks, no cache/audit integration.

import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

const ALLOWED_TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache: import('./cache.js').Cache = new (require('./cache.js').Cache)();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title.trim()) {
      throw new Error('Title must not be empty');
    }

    // Validate both users exist.
    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);

    // Cache the new task.
    (this.cache as import('./cache.js').Cache).set(task.id, task, 60000);

    // Audit.
    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });

    return task;
  }

  getTask(id: string): Task | null {
    // Check cache first.
    const cached = (this.cache as import('./cache.js').Cache).get<Task>(id);
    if (cached) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      (this.cache as import('./cache.js').Cache).set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task not found: ${id}`);
    }

    const allowed = ALLOWED_TRANSITIONS[task.status];
    if (!allowed.includes(status)) {
      throw new Error(`Invalid status transition: ${task.status} -> ${status}`);
    }

    const previousStatus = task.status;
    task.status = status;

    // Invalidate cache on status change.
    (this.cache as import('./cache.js').Cache).invalidate(id);

    // Audit.
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: task.id,
      details: `${previousStatus} -> ${status}`,
      timestamp: Date.now(),
    });

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) {
      return false;
    }

    this.tasks.delete(id);

    // Invalidate cache.
    (this.cache as import('./cache.js').Cache).invalidate(id);

    // Audit.
    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

{"content": "// CSV exporter.
// Stub: returns empty string.
// Missing: permission check, field selection, CSV escaping.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function csvEscape(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return '"' + value.replace(/"/g, '""') + '"';
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied: only admins can export');
  }

  const tasks = Array.from(
    (taskManager as { tasks: Map<string, import('./tasks.js').Task> }).tasks.values()
  );

  const lines: string[] = ['id,title,status,assignee,createdAt'];

  for (const task of tasks) {
    const row = [
      task.id,
      csvEscape(task.title),
      task.status,
      task.assignee,
      String(task.createdAt),
    ].join(',');
    lines.push(row);
  }

  const csv = lines.join('\n');

  record({
    action: 'export',
    userId,
    details: `${tasks.length} tasks exported`,
    timestamp: Date.now(),
  });

  return csv;
}
", "path": "src/exporter.ts"}

