// In-memory cache with TTL.
// Buggy: get() returns undefined on miss instead of null.
// Missing: invalidate method.

type CacheEntry<T> = { value: T; expiresAt: number };

// Module-level store so every Cache instance (including ones created by
// external callers and integration tests) shares the same backing map.
const store = new Map<string, CacheEntry<unknown>>();

export class Cache {
  set<T>(key: string, value: T, ttlMs: number) {
    store.set(key, { value, expiresAt: Date.now() + ttlMs });
  }

  get<T>(key: string): T | null {
    const entry = store.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      store.delete(key);
      return null;
    }
    return entry.value as T;
  }

  invalidate(key: string) {
    store.delete(key);
  }
}
